sys_rte_eb_multiple_input_output_script_.script:
/* Example Script 
 // In this example the script input fields are 'field1', 'field2' - replace these with the fields used as script inputs // There is a static field 'input' that has all the input field values concatenated with a '|' 
 (function(batch, output) {
     for (var i = 0; i < batch.length; i++) {

         //step1: access the input variables
         var a = batch[i].field1; //Value of the first source field. 
         var b = batch[i].field2; //Value of the second source field. 

         //step2: Your script/code goes here.
         var c = a + b;

         //step3: set the output for each elements
         // In this example, 'field3', 'field4' are the target fields
         // Address output fields akin to input fields
         output[i].field3 = b;
         output[i].field4 = c;
     }

 })(batch, output);
 */

(function(batch, output) {
    for (var i = 0; i < batch.length; i++) {
        var a = batch[i].u_payload;
        gs.info('fqdn 1check parse a - ' + a);
        var c = JSON.parse(a);

        output[i].serial_number = c.servers[0].serialNumber;
        output[i].fqdn = c.servers[0].hostName + '.' + c.servers[0].dnsDomain;
		output[i].host_name = c.servers[0].hostName;
		output[i].dns_domain = c.servers[0].dnsDomain;
		output[i].name = c.servers[0].hostName;
		output[i].discovery_source = c.sourceSystem;
        gs.info('fqdn 2 output serial number - ' + output[i].serial_number);
		gs.info('fqdn 2 output fqdn - ' + output[i].fqdn);
		gs.info('fqdn 2 output host name - ' + output[i].host_name);
		gs.info('fqdn 2 output dns domain - ' + output[i].dns_domain);
		gs.info('fqdn 2 output name - ' + output[i].name);
		gs.info('fqdn 2 output discovery source - ' + output[i].discovery_source);
    }
})(batch, output);
